package dev.paddock.pocket;
import android.app.*;
import android.appwidget.AppWidgetManager;
import android.content.*;
import android.graphics.Color;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.webkit.*;
import android.widget.*;
import org.json.*;

/** Production website, with scoped OS actions and no JavaScript credential bridge. */
public class MainActivity extends Activity {
 static final String BACK_SCRIPT="(function(){var dialogs=document.querySelectorAll('dialog[open]');if(!dialogs.length)return false;var dialog=dialogs[dialogs.length-1];if(dialog.dispatchEvent(new Event('cancel',{cancelable:true})))dialog.close();return true;})()";
 static final String FOLLOWING_SCRIPT="(function(){try{var raw=localStorage.getItem('paddock-following-v1');var ids=raw?JSON.parse(raw).driverIds:[];if(!Array.isArray(ids))return '';return ids.slice(0,3).filter(function(id){return typeof id==='string'&&/^[a-f0-9-]{36}$/i.test(id);}).join(',');}catch(e){return '';}})()";
 static final String SITE="https://f1.xiaodinglab.com",HOST="f1.xiaodinglab.com";
 private WebView web;private FrameLayout root;private ValueCallback<Uri[]> chooser;private long checked;private String exportToken;private byte[] exportBytes;
 private final Handler startup=new Handler(Looper.getMainLooper());private boolean ready,fallbackAttempted;private volatile boolean bundledHome;private View recovery,startupCover;private long activeDownload=-1;
 private final Runnable startupTimeout=()->{if(!ready&&!isFinishing())recover(true);};
 boolean trusted(String url){if(url==null)return false;Uri u=Uri.parse(url);return "https".equals(u.getScheme())&&HOST.equals(u.getHost())&&(u.getPort()==-1||u.getPort()==443);}
 @Override public void onCreate(Bundle state){
  super.onCreate(state);getWindow().setStatusBarColor(Color.rgb(13,16,23));getWindow().setNavigationBarColor(Color.rgb(13,16,23));root=new FrameLayout(this);root.setBackgroundColor(Color.rgb(13,16,23));setContentView(root);
  root.setOnApplyWindowInsetsListener((v,i)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets s=i.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(s.left,s.top,s.right,s.bottom);}else v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});
  web=new WebView(this);root.addView(web,new FrameLayout.LayoutParams(-1,-1));web.setBackgroundColor(Color.rgb(13,16,23));WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setTextZoom(100);s.setMediaPlaybackRequiresUserGesture(true);s.setUserAgentString(s.getUserAgentString()+" PaddockPocket/"+getVersionName());CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);
  if(getPreferences(0).getInt("cacheVersion",0)<getVersionCode()){web.clearCache(true);getPreferences(0).edit().putInt("cacheVersion",getVersionCode()).apply();}
  web.setWebViewClient(new WebViewClient(){
   @Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){if(!request.isForMainFrame())return false;Uri u=request.getUrl();if("paddock".equals(u.getScheme())){if(trusted(view.getUrl())){if("ready".equals(u.getHost()))markReady();else if("save-file".equals(u.getHost()))saveFile(u);else if("sync-following".equals(u.getHost()))syncFollowing();else if(request.hasGesture())action(u.getHost());}return true;}if(apkUrl(u)){downloadApk(u);return true;}if(trusted(u.toString()))return false;external(u);return true;}
   @Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){if(!"GET".equals(r.getMethod())||!trusted(r.getUrl().toString()))return null;return BundledWeb.response(getAssets(),r.getUrl().getPath(),bundledHome&&r.isForMainFrame());}
   @Override public void onPageStarted(WebView v,String url,android.graphics.Bitmap icon){if(trusted(url)){hideRecovery();startup.removeCallbacks(startupTimeout);if("/".equals(Uri.parse(url).getPath())){ready=false;showStartup();startup.postDelayed(startupTimeout,4000);}else hideStartup();}}
   @Override public void onReceivedError(WebView v,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame())recover(trusted(r.getUrl().toString())&&"/".equals(r.getUrl().getPath()));}
   @Override public void onReceivedHttpError(WebView v,WebResourceRequest r,WebResourceResponse e){if(r.isForMainFrame()&&e.getStatusCode()>=500)recover("/".equals(r.getUrl().getPath()));}
   @Override public void onPageFinished(WebView v,String url){if(trusted(url)){syncFollowing();checkUpdate(false);}}
  });
  web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> callback,FileChooserParams params){if(!trusted(v.getUrl()))return false;if(chooser!=null)chooser.onReceiveValue(null);chooser=callback;try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("image/*"),31);}catch(Exception e){chooser.onReceiveValue(null);chooser=null;}return true;}});
  web.setDownloadListener((url,ua,disposition,mime,length)->{if(trusted(web.getUrl())&&url.startsWith("blob:"+SITE+"/"))exportBlob(url);else if(apkUrl(Uri.parse(url)))downloadApk(Uri.parse(url));else external(Uri.parse(url));});showStartup();if(state==null||web.restoreState(state)==null)web.loadUrl(SITE+"/");RaceWidget.schedule(this);RaceWidget.refreshInApp(this);
  if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,()->back());
 }
 void markReady(){ready=true;startup.removeCallbacks(startupTimeout);hideStartup();hideRecovery();syncFollowing();}
 void showStartup(){if(startupCover!=null)return;LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setGravity(Gravity.CENTER);box.setBackgroundColor(Color.rgb(13,16,23));ImageView logo=new ImageView(this);logo.setImageResource(dev.paddock.pocket.R.drawable.app_icon);int size=(int)(64*getResources().getDisplayMetrics().density);box.addView(logo,new LinearLayout.LayoutParams(size,size));TextView name=new TextView(this);name.setText("围场口袋");name.setTextColor(Color.WHITE);name.setTextSize(28);name.setGravity(Gravity.CENTER);name.setPadding(0,24,0,28);box.addView(name);ProgressBar progress=new ProgressBar(this);progress.setIndeterminateTintList(android.content.res.ColorStateList.valueOf(Color.rgb(95,226,195)));box.addView(progress,new LinearLayout.LayoutParams(size/2,size/2));TextView note=new TextView(this);note.setText("正在准备你的比赛周末…");note.setTextSize(14);note.setTextColor(Color.LTGRAY);note.setPadding(0,28,0,0);box.addView(note);startupCover=box;root.addView(box,new FrameLayout.LayoutParams(-1,-1));}
 void hideStartup(){if(startupCover!=null){View cover=startupCover;startupCover=null;cover.animate().alpha(0).setDuration(180).withEndAction(()->root.removeView(cover)).start();}}
 boolean apkUrl(Uri uri){String path=uri.getPath();return trusted(uri.toString())&&path!=null&&(path.matches("/downloads/Paddock-Pocket-[0-9.]+\\.apk")||"/download/android".equals(path));}
 void downloadApk(Uri uri){if(!apkUrl(uri))return;try{DownloadManager manager=(DownloadManager)getSystemService(DOWNLOAD_SERVICE);if(activeDownload!=-1){try(android.database.Cursor cursor=manager.query(new DownloadManager.Query().setFilterById(activeDownload))){if(cursor!=null&&cursor.moveToFirst()){int status=cursor.getInt(cursor.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS));if(status==DownloadManager.STATUS_PENDING||status==DownloadManager.STATUS_RUNNING||status==DownloadManager.STATUS_PAUSED){Toast.makeText(this,"安装包正在下载，请查看系统下载通知",Toast.LENGTH_LONG).show();return;}}}}String file=uri.getLastPathSegment();if(file==null||!file.endsWith(".apk"))file="Paddock-Pocket-update.apk";DownloadManager.Request request=new DownloadManager.Request(uri).setTitle("围场口袋安装包").setDescription("下载完成后点通知打开安装包").setMimeType("application/vnd.android.package-archive").setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);if(Build.VERSION.SDK_INT>=29)request.setDestinationInExternalPublicDir(Environment.DIRECTORY_DOWNLOADS,file);else request.setDestinationInExternalFilesDir(this,Environment.DIRECTORY_DOWNLOADS,file);activeDownload=manager.enqueue(request);Toast.makeText(this,"已开始下载，请查看系统通知或下载列表",Toast.LENGTH_LONG).show();}catch(Exception error){new AlertDialog.Builder(this).setTitle("暂时无法开始下载").setMessage("请在浏览器打开下载页重试。").setPositiveButton("打开下载页",(d,w)->external(Uri.parse(SITE+"/download"))).setNegativeButton("返回",null).show();}}
 void hideRecovery(){if(recovery!=null){root.removeView(recovery);recovery=null;}}
 void recover(boolean home){startup.removeCallbacks(startupTimeout);hideStartup();if(home&&!fallbackAttempted){fallbackAttempted=true;bundledHome=true;web.stopLoading();web.loadUrl(SITE+"/?app_recovery=1");return;}web.stopLoading();hideRecovery();LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setGravity(Gravity.CENTER);int p=(int)(24*getResources().getDisplayMetrics().density);box.setPadding(p,p,p,p);box.setBackgroundColor(Color.rgb(13,16,23));TextView title=new TextView(this);title.setText("连接暂时中断");title.setTextColor(Color.WHITE);title.setTextSize(24);box.addView(title);TextView note=new TextView(this);note.setText("可以重新连接，或直接打开五星体育观看。账号信息不会被清除。");note.setTextColor(Color.LTGRAY);note.setTextSize(16);note.setPadding(0,p,0,p);box.addView(note);Button retry=new Button(this);retry.setText("重新连接");retry.setOnClickListener(v->{hideRecovery();bundledHome=false;fallbackAttempted=false;web.loadUrl(SITE+"/");});box.addView(retry);Button watch=new Button(this);watch.setText("观看五星体育");watch.setOnClickListener(v->startActivity(new Intent(this,LiveActivity.class)));box.addView(watch);Button browser=new Button(this);browser.setText("在浏览器打开");browser.setOnClickListener(v->external(Uri.parse(SITE+"/")));box.addView(browser);recovery=box;root.addView(box,new FrameLayout.LayoutParams(-1,-1));}
 int getVersionCode(){try{return getPackageManager().getPackageInfo(getPackageName(),0).versionCode;}catch(Exception e){return 0;}}
 String getVersionName(){try{return getPackageManager().getPackageInfo(getPackageName(),0).versionName;}catch(Exception e){return "unknown";}}
 void action(String action){if("smg-live".equals(action))startActivity(new Intent(this,LiveActivity.class));else if("open-tencent".equals(action)){Intent i=getPackageManager().getLaunchIntentForPackage("com.tencent.qqlive");if(i!=null)startActivity(i);else external(Uri.parse("https://v.qq.com/"));}else if("pin-widget".equals(action)){AppWidgetManager m=AppWidgetManager.getInstance(this);if(m.isRequestPinAppWidgetSupported())m.requestPinAppWidget(new ComponentName(this,RaceWidget.class),null,null);else Toast.makeText(this,"长按桌面 → 小组件 → 围场口袋",Toast.LENGTH_LONG).show();}else if("check-updates".equals(action))checkUpdate(true);}
 void external(Uri u){if(u==null||!("https".equals(u.getScheme())||"http".equals(u.getScheme())||"txvideo".equals(u.getScheme())))return;try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){Toast.makeText(this,"请先安装可打开此链接的应用",Toast.LENGTH_LONG).show();}}
 void checkUpdate(boolean manual){if(!manual&&System.currentTimeMillis()-checked<86400000)return;checked=System.currentTimeMillis();new Thread(()->{try{java.net.HttpURLConnection c=(java.net.HttpURLConnection)new java.net.URL(SITE+"/downloads/android-build.json").openConnection();c.setConnectTimeout(10000);c.setReadTimeout(10000);c.setInstanceFollowRedirects(false);JSONObject data;try(java.io.InputStream in=c.getInputStream()){data=new JSONObject(DataRepository.read(in));}finally{c.disconnect();}int code=data.optInt("versionCode");String path=data.optString("download");if(!path.matches("/downloads/Paddock-Pocket-[0-9.]+\\.apk"))throw new Exception();int current=getPackageManager().getPackageInfo(getPackageName(),0).versionCode;runOnUiThread(()->{if(isFinishing())return;if(code>current)new AlertDialog.Builder(this).setTitle("围场口袋有新版本").setMessage("版本 "+data.optString("version")+"，下载后按系统提示安装。网页内容随网站同步。").setPositiveButton("下载更新",(d,w)->downloadApk(Uri.parse(SITE+path))).setNegativeButton("稍后",null).show();else if(manual)Toast.makeText(this,"当前安装包已是最新版本",Toast.LENGTH_SHORT).show();});}catch(Exception e){if(manual)runOnUiThread(()->Toast.makeText(this,"暂时无法检查更新",Toast.LENGTH_LONG).show());}},"paddock-update").start();}
 void syncFollowing(){if(web==null||!trusted(web.getUrl()))return;web.evaluateJavascript(FOLLOWING_SCRIPT,value->{try{Object raw=new JSONTokener(value).nextValue();if(!(raw instanceof String))return;String saved=(String)raw;if(!saved.matches("(?i)(?:[a-f0-9-]{36}(?:,[a-f0-9-]{36}){0,2})?"))return;getSharedPreferences("paddock",0).edit().putString("favorites",saved).putString("favorite",saved.isEmpty()?"":saved.split(",")[0]).apply();RaceWidget.render(this,DataRepository.load(this));}catch(Exception ignored){}});}
 void exportBlob(String url){exportToken=java.util.UUID.randomUUID().toString();String token=JSONObject.quote(exportToken);web.evaluateJavascript("fetch("+JSONObject.quote(url)+").then(r=>r.blob()).then(b=>{if(b.size>2097152)throw Error();const r=new FileReader();r.onload=()=>{location.href='paddock://save-file?token='+encodeURIComponent("+token+")+'&data='+encodeURIComponent(String(r.result).split(',')[1]);};r.readAsDataURL(b);}).catch(()=>alert('文件暂时无法保存，请重试'))",null);}
 void saveFile(Uri u){if(exportToken==null||!exportToken.equals(u.getQueryParameter("token")))return;exportToken=null;try{String data=u.getQueryParameter("data");if(data==null||data.length()>2900000)throw new Exception();exportBytes=android.util.Base64.decode(data,android.util.Base64.DEFAULT);startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("text/calendar").putExtra(Intent.EXTRA_TITLE,"Paddock-Race.ics"),32);}catch(Exception e){exportBytes=null;}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==31&&chooser!=null){chooser.onReceiveValue(result==RESULT_OK&&data!=null&&data.getData()!=null?new Uri[]{data.getData()}:null);chooser=null;}if(request==32){final byte[] bytes=exportBytes;exportBytes=null;if(result==RESULT_OK&&bytes!=null&&data!=null&&data.getData()!=null){final Uri target=data.getData();new Thread(()->{try(java.io.OutputStream out=getContentResolver().openOutputStream(target)){if(out!=null)out.write(bytes);}catch(Exception ignored){}},"paddock-export").start();}}}
 void navigateBack(){if(web.canGoBack())web.goBack();else finish();}
 void back(){if(!trusted(web.getUrl())){navigateBack();return;}web.evaluateJavascript(BACK_SCRIPT,handled->{if(!"true".equals(handled)&&!isFinishing())navigateBack();});}
 @Override public void onBackPressed(){back();}
 @Override protected void onSaveInstanceState(Bundle state){web.saveState(state);super.onSaveInstanceState(state);}
 @Override protected void onPause(){syncFollowing();web.onPause();CookieManager.getInstance().flush();super.onPause();}
 @Override protected void onResume(){super.onResume();if(web!=null)web.onResume();}
 @Override protected void onDestroy(){startup.removeCallbacksAndMessages(null);if(chooser!=null)chooser.onReceiveValue(null);if(web!=null){web.stopLoading();root.removeView(web);web.destroy();}super.onDestroy();}
}

